import React, { useEffect, useState } from 'react';
import styled from 'styled-components';

const HeroSection = styled.section`
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: ${({ theme }) => theme.bg};
  color: ${({ theme }) => theme.text};
  text-align: center;
  padding: 0.5rem 1.5rem 2rem 1.5rem;
  opacity: ${({ animate }) => (animate ? 1 : 0)};
  transform: ${({ animate }) => (animate ? 'translateY(0)' : 'translateY(40px)')};
  transition: opacity 0.8s cubic-bezier(0.4,0,0.2,1), transform 0.8s cubic-bezier(0.4,0,0.2,1);
`;

const Intro = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 2.2rem;
`;

const IntroLine = styled.div`
  font-size: 1.08rem;
  color: ${({ theme }) => theme.text};
  opacity: 0.85;
  display: flex;
  align-items: center;
  gap: 0.5rem;
`;

const Availability = styled.span`
  display: inline-flex;
  align-items: center;
  font-size: 1.02rem;
  color: #43ff7c;
  font-weight: 500;
  margin-right: 0.5rem;
  &::before {
    content: '';
    display: inline-block;
    width: 0.7em;
    height: 0.7em;
    background: #43ff7c;
    border-radius: 50%;
    margin-right: 0.4em;
    box-shadow: 0 0 6px #43ff7c99;
  }
`;

const Name = styled.h1`
  font-size: 4.2rem;
  font-weight: 900;
  letter-spacing: -2px;
  color: ${({ theme }) => theme.text};
  margin-bottom: 0.5rem;
  line-height: 1.08;
`;

const Title = styled.h2`
  font-size: 3.1rem;
  font-weight: 800;
  color: ${({ theme }) => theme.text};
  margin-bottom: 1.2rem;
  line-height: 1.13;
`;

const Tagline = styled.p`
  font-size: 1.18rem;
  color: ${({ theme }) => theme.text};
  opacity: 0.8;
  margin-bottom: 2.8rem;
  max-width: 600px;
`;

const ButtonGroup = styled.div`
  display: flex;
  gap: 2rem;
  margin-top: 1.5rem;
`;

const HeroButton = styled.a`
  padding: 0.85rem 2.2rem;
  border-radius: 100px;
  border: 1.5px solid ${({ theme }) => theme.text};
  background: transparent;
  color: ${({ theme }) => theme.text};
  font-size: 1.08rem;
  font-weight: 600;
  text-decoration: none;
  transition: background 0.18s, color 0.18s;
  cursor: pointer;
  &:hover, &:focus {
    background: ${({ theme }) => theme.text};
    color: ${({ theme }) => theme.bg};
  }
`;


const Hero = () => {
  const [animate, setAnimate] = useState(false);
  useEffect(() => {
    setAnimate(true);
  }, []);
  return (
    <HeroSection id="hero" animate={animate}>
      <Intro>
        <IntroLine>
          <span role="img" aria-label="waving hand">👋</span>
          HELLO, I'M VALDRIN SHALA
Frontend Developer & UI Builder
        </IntroLine>
        <IntroLine>
          <Availability>Available for work</Availability>
        </IntroLine>
      </Intro>
      <Name>Your design partner for<br />creating digital products</Name>
      <Title>
        {/* Optionally, you can add a subheadline here or remove this if not needed */}
      </Title>
      <Tagline>
       HELLO, I'M VALDRIN SHALA
Frontend Developer & UI Builder
      </Tagline>
      <ButtonGroup>
        <HeroButton href="#projects">View Projects</HeroButton>
        <HeroButton href="#contact">Book a free call</HeroButton>
      </ButtonGroup>
    </HeroSection>
  );
};

export default Hero;
